  <div class="app">
    <section class="auth-screen" id="authView" aria-live="polite">
      <div class="auth-card">
        <div class="auth-header">
          <div class="brand">
            <span class="brand-mark" aria-hidden="true"></span>
            <div>
              <h1>Dawn Webber Maths Tutoring</h1>
              <p>Sign in to collaborate with your tutor.</p>
            </div>
          </div>
        </div>
        <div class="auth-tabs" role="tablist">
          <button class="auth-tab is-active" id="tabSignIn" type="button" role="tab">Sign In</button>
          <button class="auth-tab" id="tabSignUp" type="button" role="tab">Sign Up</button>
          <button class="auth-tab" id="tabConfirm" type="button" role="tab">Confirm</button>
        </div>
        <div class="auth-panel" id="panelSignIn" role="tabpanel">
          <form id="signInForm">
            <label>
              Email
              <input id="signInEmail" type="email" autocomplete="email" required />
            </label>
            <label>
              Password
              <input id="signInPassword" type="password" autocomplete="current-password" required />
            </label>
            <button type="submit">Sign In</button>
            <button class="link-button" type="button" id="needConfirm">Need a confirmation code?</button>
          </form>
        </div>
        <div class="auth-panel" id="panelSignUp" role="tabpanel" hidden>
          <form id="signUpForm">
            <label>
              Email
              <input id="signUpEmail" type="email" autocomplete="email" required />
            </label>
            <label>
              Password
              <input id="signUpPassword" type="password" autocomplete="new-password" required />
            </label>
            <button type="submit">Create Account</button>
          </form>
        </div>
        <div class="auth-panel" id="panelConfirm" role="tabpanel" hidden>
          <form id="confirmForm">
            <label>
              Email
              <input id="confirmEmail" type="email" autocomplete="email" required />
            </label>
            <label>
              Confirmation Code
              <input id="confirmCode" type="text" inputmode="numeric" autocomplete="one-time-code" required />
            </label>
            <button type="submit">Confirm Account</button>
            <button class="secondary" type="button" id="resendCode">Resend Code</button>
          </form>
        </div>
        <div class="auth-message" id="authMessage" role="status"></div>
      </div>
    </section>
    <section class="board-screen" id="boardView" hidden>
      <div id="whiteboardAppBarContainer"></div>
      <main class="board-layout">
        <aside class="board-left-rail" aria-label="PDF pages">
          <div class="pdf-sidebar" id="pdfSidebar" hidden></div>
        </aside>
        <section class="board-center">
          <div class="board" id="boardStage">
            <div class="connection-error" id="connectionError" role="alert" hidden></div>
            <div class="stroke-loading" id="strokeLoading" role="status" aria-live="polite" hidden>
              <div class="stroke-loading-card">
                <span class="stroke-loading-spinner" aria-hidden="true"></span>
                <span class="stroke-loading-text" id="strokeLoadingLabel">Loading…</span>
              </div>
            </div>
            <div class="pdf-layer" id="pdfLayer" aria-hidden="true">
              <div class="pdf-viewer" id="pdfViewer" hidden>
                <canvas id="pdfCanvas" aria-label="PDF page"></canvas>
              </div>
            </div>
            <canvas id="board" role="img" aria-label="Drawing board"></canvas>
            <div id="eraserIndicator" class="eraser-indicator" hidden></div>
            <div class="student-panel" id="studentPanel" hidden>
              <div class="student-panel-header">
                <div>
                  <h2>Students</h2>
                  <p>Select students to work with</p>
                </div>
                <button class="student-panel-close" id="studentClose" type="button" aria-label="Close student list">×</button>
              </div>
              <div class="student-panel-search">
                <input id="studentSearchInput" type="search" placeholder="Search by name or email" />
              </div>
              <div class="student-panel-status" id="studentStatus"></div>
              <button class="student-panel-clear" id="studentClear" type="button" hidden>Clear Students</button>
              <div class="student-results" id="studentResults"></div>
            </div>
            <div class="pdf-panel" id="pdfPanel" hidden>
              <div class="pdf-panel-header">
                <div>
                  <h2>PDF Library</h2>
                  <p>Search the Cambridge papers index</p>
                </div>
                <button class="pdf-panel-close" id="pdfClose" type="button" aria-label="Close PDF search">×</button>
              </div>
              <div class="pdf-panel-search">
                <input id="pdfSearchInput" type="search" placeholder="Search by filename, year, or session" />
              </div>
              <div class="pdf-panel-filters">
                <label class="pdf-filter-checkbox">
                  <input type="checkbox" id="filterWS" />
                  <span>WS</span>
                </label>
                <label class="pdf-filter-checkbox">
                  <input type="checkbox" id="filterQP" checked />
                  <span>QP</span>
                </label>
                <label class="pdf-filter-checkbox">
                  <input type="checkbox" id="filterMS" />
                  <span>MS</span>
                </label>
                <label class="pdf-filter-checkbox pdf-filter-tutor-only" id="filterASLabel" hidden>
                  <input type="checkbox" id="filterAS" checked />
                  <span>AS</span>
                </label>
                <label class="pdf-filter-checkbox pdf-filter-tutor-only" id="filterIGLabel" hidden>
                  <input type="checkbox" id="filterIG" checked />
                  <span>IG</span>
                </label>
              </div>
              <div class="pdf-panel-status" id="pdfStatus"></div>
              <button class="pdf-panel-clear" id="pdfClear" type="button" hidden>Clear PDF</button>
              <div class="pdf-results" id="pdfResults"></div>
            </div>
          </div>
        </section>
        <aside class="board-right-rail" aria-label="Editing tools">
          ${$m()}
        </aside>
      </main>
    </section>
  </div>
